import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		
		while(t != 0){
		    int n = sc.nextInt();
		    long[] nums = new long[3 * n];
		    
		    for(int i = 0; i < 3 * n; i++){
		        nums[i] = sc.nextLong();
		    }
		    
		    Arrays.sort(nums);
		    
		    long[] prefix = new long[3 * n + 1];
		    for(int i = 0; i < 3 * n; i++){
		        prefix[i + 1] = prefix[i] + nums[3 * n - 1 - i];
		    }
		    
		    for(int i = 0; i < (3 * n) / 2; i++){
		        long temp = nums[i];
		        nums[i] = nums[3 * n - i - 1];
		        nums[3 * n - 1 - i] = temp;
		    }
		    
		    long ans = 0;
		    
		    for(int k = 0; k <= n; k++){
		        int maxLeft = n - k;
		        
		        int left = 0, right = maxLeft;
		        
		        while(left < right){
		            int mid = (left + right + 1) / 2;
		            
		            int l = mid - 1;
		            long curr = nums[k + 2 * l] + nums[k + 2 * l + 1] - 3L * nums[3 * n - 2 * k - 1 - l];
		            
		            if(curr >= 0){
		                left = mid;
		            }
		            else{
		                right = mid - 1;
		            }
		        }
		        
		        int l = left;
		        
		        int r = 3 * n - 2 * k - l;
		        
		        long curr = 2L * prefix[k] + prefix[k + 2 * l] + 3L * prefix[r];
		        
		        ans = Math.max(ans, curr);
		    }
		    
		    System.out.println(ans);
		    
		    t--;
		}
	}
}
